using System;using System.Text;
class Program{static void Main(string[] args){if(args.Length>0&&args[0]=="transitions"){foreach(var z in TimeZoneInfo.GetSystemTimeZones()){long start=1735689600,end=1830297600,step=21600;bool previous=z.IsDaylightSavingTime(DateTimeOffset.FromUnixTimeSeconds(start).UtcDateTime);for(long t=start+step;t<=end;t+=step){bool current=z.IsDaylightSavingTime(DateTimeOffset.FromUnixTimeSeconds(t).UtcDateTime);if(current!=previous){long low=t-step,high=t;while(high-low>1){long mid=low+(high-low)/2;if(z.IsDaylightSavingTime(DateTimeOffset.FromUnixTimeSeconds(mid).UtcDateTime)==previous)low=mid;else high=mid;}foreach(long d in new long[]{-1,0,1})Console.WriteLine(Convert.ToHexString(Encoding.UTF8.GetBytes(z.Id))+" "+(high+d));}previous=current;}}return;}if(args.Length>0){foreach(var zone in TimeZoneInfo.GetSystemTimeZones())Console.WriteLine(zone.Id);return;}string line;while((line=Console.ReadLine())!=null){try{var parts=line.Split(' ');string id=parts[0]=="-"?null:parts[0]=="."?"":parts[0]=="local"?"local":Encoding.UTF8.GetString(Convert.FromHexString(parts[0]));var zone=id=="local"?TimeZoneInfo.Local:TimeZoneInfo.FindSystemTimeZoneById(id);Console.WriteLine(zone.IsDaylightSavingTime(DateTimeOffset.FromUnixTimeSeconds(long.Parse(parts[1])).UtcDateTime)?"Y":"N");}catch{Console.WriteLine("E");}}}}
